INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_56d1e6ee2d41ff791ad3','Helwan National University','جامعة حلوان الأهلية','HNU','helwan-national-university','NATIONAL','Egypt','مصر','Helwan','حلوان','Helwan National University is a national (ahliya) university affiliated with Helwan University, founded in 2022 and based in Ain Helwan, Cairo. Its faculties cover medicine, dentistry, physical therapy, applied health sciences, engineering, computer science and IT, sciences, arts and applied arts, and humanities, commerce and business administration, including legal studies in Arabic and English. Fees for 2026/2027 range from 55,000 to 150,000 EGP a year depending on the faculty.','جامعة حلوان الأهلية جامعة أهلية تابعة لجامعة حلوان، أُنشئت عام 2022 ومقرها عين حلوان بالقاهرة. تضم كليات الطب والجراحة، وطب الفم والأسنان، والعلاج الطبيعي، وتكنولوجيا العلوم الصحية التطبيقية، والهندسة، والحاسبات وتكنولوجيا المعلومات، والعلوم، والفنون والفنون التطبيقية، والعلوم الإنسانية والتجارة وإدارة الأعمال، ومنها برامج الدراسات القانونية بالعربية والإنجليزية. تتراوح مصروفات العام 2026/2027 بين 55 و150 ألف جنيه سنويًا حسب الكلية.','https://www.hnu.edu.eg','/img/universities/helwan-national-university/logo.webp','/img/universities/helwan-national-university/cover.jpg',2022,'Ain Helwan, Helwan, Cairo','عين حلوان، حلوان، القاهرة',NULL,NULL,29.870366175011753,31.319581725700534,now(),now(),now());
