INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_f1d74b013063d2a41b29','Menoufia National University','جامعة المنوفية الأهلية',NULL,'menoufia-national-university','NATIONAL','Egypt','مصر','Tukh Tanbasha','طوخ طنبشا','Menoufia National University is a national (ahliya) university affiliated with Menoufia University, founded in 2022 in Tukh Tanbasha, Menoufia Governorate. It teaches medicine, dentistry, physical therapy, pharmacy, veterinary medicine, nursing, applied health sciences, engineering, and computing and artificial intelligence. Fees for 2026/2027 range from 60,000 to 150,000 EGP depending on the faculty, plus a non-refundable 1,500 EGP application fee.','جامعة المنوفية الأهلية جامعة أهلية تابعة لجامعة المنوفية، أُنشئت عام 2022 في طوخ طنبشا بمحافظة المنوفية. تضم كليات الطب البشري، وطب الأسنان، والعلاج الطبيعي، والصيدلة، والطب البيطري، والتمريض، والعلوم الصحية التطبيقية، والهندسة، والحاسبات والذكاء الاصطناعي. تتراوح مصروفات العام 2026/2027 بين 60 و150 ألف جنيه حسب الكلية، إضافة إلى رسوم تقديم إدارية قدرها 1500 جنيه غير مستردة.',NULL,NULL,NULL,2022,'Tukh Tanbasha, Menoufia Governorate','طوخ طنبشا، محافظة المنوفية',NULL,NULL,30.610131398494,31.109886535997,now(),now(),now());
