INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_3e1d01658648e79032e6','Beni Suef National University','جامعة بني سويف الأهلية',NULL,'beni-suef-national-university','NATIONAL','Egypt','مصر','New Beni Suef','بني سويف الجديدة','Beni Suef National University is a national (ahliya) university affiliated with Beni-Suef University, founded in 2022 in New Beni Suef City. Its programs span medicine, dentistry, physical therapy, clinical pharmacy, nursing, engineering, computing and AI, sciences, navigation sciences and space technology, commerce, mass communication, arts and law. Fees for 2026/2027 run from 45,000 to 150,000 EGP a year and were not raised from the previous year.','جامعة بني سويف الأهلية جامعة أهلية تابعة لجامعة بني سويف، أُنشئت عام 2022 بمدينة بني سويف الجديدة. تشمل برامجها الطب البشري، وطب الفم والأسنان، والعلاج الطبيعي، والصيدلة الإكلينيكية، والتمريض، والهندسة، والحاسبات والذكاء الاصطناعي، والعلوم، وعلوم الملاحة وتكنولوجيا الفضاء، والتجارة، والإعلام، والآداب، والحقوق. تتراوح مصروفات العام 2026/2027 بين 45 و150 ألف جنيه سنويًا، دون زيادة عن العام السابق.',NULL,NULL,NULL,2022,'New Beni Suef City, Beni Suef Governorate','مدينة بني سويف الجديدة، محافظة بني سويف',NULL,NULL,29.034709310767,31.121882111105,now(),now(),now());
