INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_55e9ef8710b3b9a068e7','South Valley National University','جامعة جنوب الوادي الأهلية',NULL,'south-valley-national-university','NATIONAL','Egypt','مصر','Qena','قنا','South Valley National University is a national (ahliya) university in Qena, founded in 2022 alongside South Valley University (since renamed Qena University). It teaches medicine, dentistry, physical therapy, pharmacy, nursing, engineering, computing and AI, administrative sciences in English or Arabic, and languages (Al-Alsun) in English or French. Published 2026/2027 fees range from 30,000 to 150,000 EGP a year; administrative fees may be added.','جامعة جنوب الوادي الأهلية جامعة أهلية بمدينة قنا، أُنشئت عام 2022 إلى جانب جامعة جنوب الوادي (التي أصبح اسمها جامعة قنا). تضم الطب والجراحة، وطب الفم والأسنان، والعلاج الطبيعي، والصيدلة، والتمريض، والهندسة، والحاسبات والذكاء الاصطناعي، والعلوم الإدارية بالإنجليزية أو العربية، والألسن بالإنجليزية أو الفرنسية. تتراوح المصروفات المعلنة للعام 2026/2027 بين 30 و150 ألف جنيه سنويًا، وقد تُضاف رسوم إدارية.','https://www.svnu.edu.eg',NULL,NULL,2022,'Qena, Qena Governorate','قنا، محافظة قنا',NULL,NULL,26.202611111111,32.746305555556,now(),now(),now());
