INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_e60df191fe37fe4dcd3e','East Port Said National University','جامعة شرق بورسعيد الأهلية',NULL,'east-port-said-national-university','NATIONAL','Egypt','مصر','Salam Misr City','مدينة سلام مصر','East Port Said National University is a national (ahliya) university founded in 2022 in Salam Misr City, east of Port Said. It has faculties of medicine, pharmacy, engineering, computer science and IT, applied health sciences technology, business sciences and arts. Fees for 2026/2027 range from 40,000 to 149,000 EGP a year, plus administrative fees of 3% of tuition; fees are paid in two installments.','جامعة شرق بورسعيد الأهلية جامعة أهلية أُنشئت عام 2022 بمدينة سلام مصر شرق بورسعيد. تضم كليات الطب، والصيدلة، والهندسة، وعلوم الحاسب وتقنية المعلومات، وتكنولوجيا العلوم الصحية التطبيقية، وعلوم الأعمال، والآداب. تتراوح مصروفات العام 2026/2027 بين 40 و149 ألف جنيه سنويًا، إضافة إلى مصروفات إدارية بنسبة 3% من المصروفات الدراسية، وتُسدد على قسطين.','https://epnu.edu.eg',NULL,NULL,2022,'Salam Misr City, East Port Said','مدينة سلام مصر، شرق بورسعيد',NULL,NULL,31.021659768479,32.626969292446,now(),now(),now());
