INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_67fdd4df52950e628660','Zagazig National University','جامعة الزقازيق الأهلية',NULL,'zagazig-national-university','NATIONAL','Egypt','مصر','10th of Ramadan City','مدينة العاشر من رمضان','Zagazig National University is a national (ahliya) university affiliated with Zagazig University, on a 44-feddan campus in 10th of Ramadan City, Sharqia. It has seven faculties: medicine, dentistry, pharmacy, nursing, engineering, computers and information, and commerce. Fees for 2026/2027 range from 40,000 to 130,000 EGP a year, plus a non-refundable 1,500 EGP file fee per program.','جامعة الزقازيق الأهلية جامعة أهلية تابعة لجامعة الزقازيق، تقع على مساحة 44 فدانًا بمدينة العاشر من رمضان بمحافظة الشرقية. تضم سبع كليات: الطب البشري، وطب وجراحة الفم والأسنان، والصيدلة، والتمريض، والهندسة، والحاسبات والمعلومات، والتجارة. تتراوح مصروفات العام 2026/2027 بين 40 و130 ألف جنيه سنويًا، إضافة إلى رسوم فتح ملف قدرها 1500 جنيه غير مستردة لكل برنامج.','https://www.znu.edu.eg',NULL,NULL,2022,'10th of Ramadan City, Sharqia Governorate','مدينة العاشر من رمضان، محافظة الشرقية',NULL,NULL,30.241231840748,31.701956855387,now(),now(),now());
