INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_4cdab06fb64edce9910d','New Ismailia National University','جامعة الإسماعيلية الجديدة الأهلية','NINU','new-ismailia-national-university','NATIONAL','Egypt','مصر','New Ismailia','الإسماعيلية الجديدة','New Ismailia National University is a national (ahliya) university that grew out of Suez Canal University, on a 29-feddan campus in New Ismailia City on the east bank of the Suez Canal. Its eight faculties cover medicine, dentistry, pharmacy, nursing, physical therapy, applied health sciences, engineering (five-year programs) and international trade and languages, all on the credit-hour system. The board of trustees approved an indicative 2026/2027 fee schedule from 45,000 to 160,000 EGP, before administrative and service fees.','جامعة الإسماعيلية الجديدة الأهلية جامعة أهلية منبثقة من جامعة قناة السويس، تقع على مساحة 29 فدانًا بمدينة الإسماعيلية الجديدة على الضفة الشرقية لقناة السويس. تضم ثماني كليات: الطب، وطب الأسنان، والصيدلة، والتمريض، والعلاج الطبيعي، وتكنولوجيا العلوم الصحية التطبيقية، والهندسة (برامج مدتها خمس سنوات)، والتجارة الدولية واللغات، وتعمل بنظام الساعات المعتمدة. أقر مجلس الأمناء تصورًا استرشاديًا لمصروفات العام 2026/2027 بين 45 و160 ألف جنيه، دون المصروفات الإدارية ورسوم الخدمات.','https://ninu.edu.eg','/img/universities/new-ismailia-national-university/logo.png','/img/universities/new-ismailia-national-university/cover.jpg',2022,'New Ismailia City, east of the Suez Canal, Ismailia','مدينة الإسماعيلية الجديدة، شرق قناة السويس، الإسماعيلية','+20 64 320 0125','president@ninu.edu.eg',30.5853669,32.3546212,now(),now(),now());
