INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_1aaf77b63e67bc7542bf','Suez National University','جامعة السويس الأهلية','SNU','suez-national-university','NATIONAL','Egypt','مصر','Suez','السويس','Suez National University was established by Presidential Decree No. 243 of 2025 and took its first students in 2025/2026, on a campus in Madinat El Salam 1 on the Cairo-Suez road, near the New Administrative Capital and the Suez industrial zone. Its faculties include engineering, petroleum engineering, computers and AI, dentistry, physical therapy, science, applied arts, media, economics, business and political science, and languages and humanities, on the credit-hour system. Annual fees range from 45,000 to 120,000 EGP, plus a 1,400 EGP application fee and administrative fees of 3%.','أُنشئت جامعة السويس الأهلية بالقرار الجمهوري رقم 243 لسنة 2025، واستقبلت أول دفعة في العام الدراسي 2025/2026، ويقع حرمها بمدينة السلام 1 على طريق القاهرة السويس بالقرب من العاصمة الإدارية الجديدة والمنطقة الصناعية بالسويس. تضم كليات الهندسة، وهندسة البترول، والحاسبات والمعلومات والذكاء الاصطناعي، وطب الفم والأسنان، والعلاج الطبيعي، والعلوم، والفنون التطبيقية، والإعلام، والاقتصاد وإدارة الأعمال والعلوم السياسية، واللغات والعلوم الإنسانية، بنظام الساعات المعتمدة. تتراوح المصروفات السنوية بين 45 و120 ألف جنيه، إضافة إلى رسوم طلب التحاق قدرها 1400 جنيه ومصروفات إدارية بنسبة 3%.','https://snu.edu.eg','/img/universities/suez-national-university/logo.png',NULL,2025,'Madinat El Salam 1, Cairo-Suez Road, Suez','مدينة السلام 1، طريق القاهرة السويس، السويس',NULL,'admission@snu.edu.eg',29.994195479003103,32.49681358671311,now(),now(),now());
