INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_3de1f8fbe0c5ffa87377','Fayoum National University','جامعة الفيوم الأهلية',NULL,'fayoum-national-university','NATIONAL','Egypt','مصر','New Fayoum','الفيوم الجديدة','Fayoum National University is a national (ahliya) university founded in 2025 in New Fayoum City, affiliated with Fayoum University. It has seven faculties: medicine, dentistry, engineering, computing and AI, nursing, science, and languages and humanities. Fees for new students in 2026/2027 range from 44,000 to 148,000 EGP, before administrative fees, plus a 1,500 EGP file fee.','جامعة الفيوم الأهلية جامعة أهلية أُنشئت عام 2025 بمدينة الفيوم الجديدة، تابعة لجامعة الفيوم. تضم سبع كليات: الطب البشري، وطب وجراحة الفم والأسنان، والهندسة، والحاسبات والذكاء الاصطناعي، والتمريض، والعلوم، واللغات والعلوم الإنسانية. تتراوح مصروفات الطلاب الجدد للعام 2026/2027 بين 44 و148 ألف جنيه دون المصروفات الإدارية، إضافة إلى رسوم فتح ملف قدرها 1500 جنيه.','https://fnu.edu.eg',NULL,NULL,2025,'New Fayoum City, Fayoum Governorate','مدينة الفيوم الجديدة، محافظة الفيوم',NULL,NULL,NULL,NULL,now(),now(),now());
