INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_a8e163d4d08b477d5e76','Damietta National University','جامعة دمياط الأهلية','DNU','damietta-national-university','NATIONAL','Egypt','مصر','New Damietta','دمياط الجديدة','Damietta National University is a national (ahliya) university founded in 2025 in New Damietta City, sharing its president with Damietta University. It has six faculties: computers, information and AI (including cybersecurity and applied AI), nursing, arts and design (furniture design and technology, advertising, media arts), business, Al-Alsun (languages), and archaeology and tourism. Announced 2026/2027 fees range from 27,000 to 55,000 EGP depending on the faculty.','جامعة دمياط الأهلية جامعة أهلية أُنشئت عام 2025 بمدينة دمياط الجديدة، ويرأسها رئيس جامعة دمياط. تضم ست كليات: الحاسبات والمعلومات والذكاء الاصطناعي (ومنها الأمن السيبراني والذكاء الاصطناعي التطبيقي)، والتمريض، والفنون والتصميم (تصميم وتكنولوجيا الأثاث، والإعلان، وفنون الميديا)، والأعمال، والألسن، والآثار والسياحة. تتراوح المصروفات المعلنة للعام 2026/2027 بين 27 و55 ألف جنيه حسب الكلية.','https://www.dam-nu.edu.eg','/img/universities/damietta-national-university/logo.svg','/img/universities/damietta-national-university/cover.webp',2025,'New Damietta City, Damietta Governorate','مدينة دمياط الجديدة، محافظة دمياط',NULL,'info@dam-nu.edu.eg',31.424326,31.6465628,now(),now(),now());
